import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_triplet_margin_loss(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_triplet_margin_kernel(
    const float* anchor,
    const float* positive,
    const float* negative,
    float* output,
    int batch_size,
    int feature_dim,
    float margin,
    float eps)
{
    int row = blockIdx.x;
    if (row >= batch_size) {
        return;
    }

    auto a = make_tensor(
        make_gmem_ptr(anchor + static_cast<long long>(row) * feature_dim),
        make_shape(feature_dim),
        make_stride(Int<1>{}));

    auto p = make_tensor(
        make_gmem_ptr(positive + static_cast<long long>(row) * feature_dim),
        make_shape(feature_dim),
        make_stride(Int<1>{}));

    auto n = make_tensor(
        make_gmem_ptr(negative + static_cast<long long>(row) * feature_dim),
        make_shape(feature_dim),
        make_stride(Int<1>{}));

    float positive_distance = 0.0f;
    float negative_distance = 0.0f;

    for (int i = threadIdx.x; i < feature_dim; i += blockDim.x) {
        float dp = a(i) - p(i) + eps;
        float dn = a(i) - n(i) + eps;
        positive_distance += dp * dp;
        negative_distance += dn * dn;
    }

    __shared__ float positive_reduce[256];
    __shared__ float negative_reduce[256];

    int tid = threadIdx.x;
    positive_reduce[tid] = positive_distance;
    negative_reduce[tid] = negative_distance;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            positive_reduce[tid] += positive_reduce[tid + stride];
            negative_reduce[tid] += negative_reduce[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float dp = sqrtf(positive_reduce[0]);
        float dn = sqrtf(negative_reduce[0]);
        float loss = fmaxf(dp - dn + margin, 0.0f);
        atomicAdd(output, loss);
    }
}


torch::Tensor cute_triplet_margin_loss(
    torch::Tensor anchor,
    torch::Tensor positive,
    torch::Tensor negative,
    double margin)
{
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
    TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");

    TORCH_CHECK(anchor.scalar_type() == at::kFloat, "anchor must be float32");
    TORCH_CHECK(positive.scalar_type() == at::kFloat, "positive must be float32");
    TORCH_CHECK(negative.scalar_type() == at::kFloat, "negative must be float32");

    TORCH_CHECK(anchor.dim() == 2, "anchor must be a 2D tensor");
    TORCH_CHECK(positive.dim() == 2, "positive must be a 2D tensor");
    TORCH_CHECK(negative.dim() == 2, "negative must be a 2D tensor");

    TORCH_CHECK(anchor.sizes() == positive.sizes(),
                "anchor and positive must have identical shapes");
    TORCH_CHECK(anchor.sizes() == negative.sizes(),
                "anchor and negative must have identical shapes");

    auto anchor_c = anchor.contiguous();
    auto positive_c = positive.contiguous();
    auto negative_c = negative.contiguous();

    const int batch_size = static_cast<int>(anchor_c.size(0));
    const int feature_dim = static_cast<int>(anchor_c.size(1));

    auto output = torch::zeros({}, anchor.options());

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    constexpr int threads = 256;
    cute_triplet_margin_kernel<<<batch_size, threads, 0, stream>>>(
        anchor_c.data_ptr<float>(),
        positive_c.data_ptr<float>(),
        negative_c.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        feature_dim,
        static_cast<float>(margin),
        1.0e-6f);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE triplet margin kernel launch failed");

    return output / static_cast<float>(batch_size);
}
"""


cute_ext = load_inline(
    name="cute_triplet_margin_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_triplet_margin_loss"],
    extra_cflags=[
        "-O3",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super().__init__()
        self.margin = float(margin)
        self._ext = cute_ext

    def forward(self, anchor, positive, negative):
        return self._ext.cute_triplet_margin_loss(
            anchor,
            positive,
            negative,
            self.margin,
        )

